pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0xb11b2fed6c9354f7aa2f658d3b4d7b31d8a13b77.sol";

contract DepositProxyTest is Test {
    DepositProxy proxyContract;
    address owner = address(0x1);
    address attacker = address(0x2);

    // Target contract that will fail when receiving ETH
    address failingContract;

    function setUp() public {
        vm.deal(owner, 10 ether);
        vm.deal(attacker, 1 ether);

        // Deploy DepositProxy with owner
        vm.prank(owner);
        proxyContract = new DepositProxy{value: 1 ether}();

        // Create a contract that will fail when receiving ETH
        failingContract = address(new FailingContract());
    }

    function testUncheckedLowLevelCall() public {
        uint256 initialProxyBalance = proxyContract.getContractBalance();
        uint256 initialAttackerBalance = attacker.balance;

        // Attempt to proxy ETH to failing contract
        bytes memory data = abi.encodeWithSignature("nonExistentFunction()");
        vm.prank(attacker);
        proxyContract.proxy{value: 1 ether}(failingContract, data);

        // Verify:
        // 1. Proxy contract balance increased by attacker's ETH (silent failure)
        // 2. Attacker balance decreased by 1 ether
        // 3. Failing contract didn't receive the ETH
        assertEq(proxyContract.getContractBalance(), initialProxyBalance + 1 ether, "Proxy balance should increase");
        assertEq(attacker.balance, initialAttackerBalance - 1 ether, "Attacker balance should decrease");
        assertEq(address(failingContract).balance, 0, "Failing contract should not receive ETH");
    }
}

contract FailingContract {
    // This contract will fail when receiving ETH since it has no payable fallback
    function nonExistentFunction() external pure returns (bool) {
        return true;
    }
}
